/* ---------- ∞·econ: a chain of rates is a composite, and its rate is the product ---------- */
const MONEY_I=[['USD','CAD','MXN',1.39,13.2],['EUR','USD','JPY',1.1,150],['GBP','EUR','SEK',1.2,11],['USD','CAD','JPY',1.4,110],['EUR','GBP','INR',0.8,105],['CAD','USD','MXN',0.7,18]];
