  const re=s=>s.replace(/(^|[^a-zA-Z])n(?![a-zA-Z])/g,(m,pre)=>pre+to), up=r=>r.replace(/\blines? [\d, and]+/g,m=>m.replace(/\d+/g,d=>+d+1));
