  if(t.t==='+'){ let nu=[Q(0)], de=[Q(1)]; for(const u of t.a){ const r=ratParts(u); if(!r) return null; nu=CH.padd(pmul(nu,r[1]),pmul(r[0],de)); de=pmul(de,r[1]); } return [ptrim(nu),ptrim(de)]; }
